const ico=(name:string,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]}"/></svg>`;
const LAUREL=`<svg class="laurel" viewBox="0 0 40 64" aria-hidden="true"><path d="M31 61C11 52 5 31 15 5" fill="none" stroke="#a8620f" stroke-width="2.6" stroke-linecap="round"/>${[[19,53,-55],[12,44,-35],[8.5,34,-15],[8.5,24,5],[11,14.5,25],[16,6.5,45]].map(([x,y,r])=>`<ellipse cx="${x}" cy="${y}" rx="7" ry="3.4" transform="rotate(${r} ${x} ${y})"/>`).join('')}${[[22,46,30],[16,37,15],[14,27,0],[16,18,-15]].map(([x,y,r])=>`<ellipse cx="${x}" cy="${y}" rx="5.5" ry="2.8" transform="rotate(${r} ${x} ${y})"/>`).join('')}</svg>`;
const ROLE_ICONS=['sword','swirl','cross','arrow'];

/** Browser presentation over the shared Cocos battlefield. All actions use model transactions. */
export class SecondEditionUI{
 readonly root:HTMLDivElement;private backdrop:HTMLDivElement;private modal:HTMLDivElement;private content:HTMLElement;
 private actions=new Map<string,()=>void>();private serial=0;private selected=0;private pool=0;private category=0;private part=-1;private quality=-1;private reverse=false;private dungeonTab=0;private difficulty=0;private page:Page='adventure';private inSecondary=false;
 private urls:Record<string,string>={};private lastReceipt='';private lastOffline:unknown=null;private toastTimer:any;private lastUpdate=0;
 get blocksBattle(){return this.inSecondary||this.modal.childElementCount>0;}
 private onKey=(e:KeyboardEvent)=>{if(e.key==='Escape'){if(this.modal.childElementCount)this.close();else if(this.inSecondary)this.root.querySelector<HTMLButtonElement>('.secondary-close')?.click();}};
 constructor(private port:Bridge,textures:Record<string,Texture2D>){
  for(const name of Object.keys(textures))this.urls[name]=this.source(textures[name]);
  this.prepareAtlas(textures);
  const style=document.createElement('style');style.id='second-edition-style';style.textContent=SECOND_EDITION_STYLES;document.head.appendChild(style);
  this.backdrop=document.createElement('div');this.backdrop.id='s6-backdrop';document.body.appendChild(this.backdrop);
  this.root=document.createElement('div');this.root.id='s6-v2';this.root.setAttribute('aria-label','森林挂机冒险');this.root.innerHTML='<main class="v2-content"></main><div class="v2-modal-host"></div><div class="v2-toast" role="status"></div>';
  for(const [key,value] of [['gold',this.urls.control0],['cream',this.urls.control1],['panel',this.urls.control2],['plaque',this.urls.control3],['close',this.urls.roundClose||this.urls.control4],['peach',this.urls.peach||this.urls.control1]])this.root.style.setProperty('--'+key+'-art',`url("${value}")`);document.body.appendChild(this.root);this.content=this.root.querySelector('main')!;this.modal=this.root.querySelector('.v2-modal-host')!;
  this.root.addEventListener('click',e=>{const b=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(b&&!b.hasAttribute('disabled')){e.stopPropagation();this.actions.get(b.dataset.action!)?.();this.pruneActions();}});
  const viewport=document.querySelector('meta[name=viewport]');if(viewport&&!viewport.getAttribute('content')?.includes('viewport-fit'))viewport.setAttribute('content',viewport.getAttribute('content')+', viewport-fit=cover');
  document.addEventListener('keydown',this.onKey);
  this.draw();window.dispatchEvent(new Event('resize'));
 }
 private source(t:Texture2D){const i:any=t.image;return i?.nativeAsset?.src||i?.data?.src||i?.nativeUrl||'';}
 private crop(t:Texture2D,x:number,y:number,w:number,h:number){const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d')!;const img:any=t.image.data;ctx.drawImage(img,x,y,w,h,0,0,w,h);return canvas.toDataURL('image/png');}
 private fitArt(source:CanvasImageSource,width:number,height:number,padding=.06){const raw=document.createElement('canvas');raw.width=width;raw.height=height;const ctx=raw.getContext('2d')!;ctx.drawImage(source,0,0,width,height);const pixels=ctx.getImageData(0,0,width,height).data;let left=width,top=height,right=0,bottom=0;for(let y=0;y<height;y++)for(let x=0;x<width;x++)if(pixels[(y*width+x)*4+3]>32){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}if(left>right)return raw.toDataURL();const out=document.createElement('canvas');out.width=out.height=256;const c=out.getContext('2d')!,w=right-left+1,h=bottom-top+1,scale=256*(1-padding*2)/Math.max(w,h);c.drawImage(raw,left,top,w,h,(256-w*scale)/2,(256-h*scale)/2,w*scale,h*scale);return out.toDataURL();}
 private prepareAtlas(t:Record<string,Texture2D>){
  const bg=t['v2-backgrounds'];for(let i=0;i<6;i++){const inset=4;this.urls['scene'+i]=this.crop(bg,i%2*bg.width/2+inset,Math.floor(i/2)*bg.height/3+inset,bg.width/2-inset*2,bg.height/3-inset*2);}
  for(const name of ['hero-knight','hero-mage','hero-priest','hero-archer']){const a=t[name];this.urls[name]=this.fitArt(a.image.data as CanvasImageSource,a.width,a.height);}
  const monsters=t['monsters-4'];for(let i=0;i<4;i++)this.urls['monster'+i]=this.crop(monsters,i%2*monsters.width/2,Math.floor(i/2)*monsters.height/2,monsters.width/2,monsters.height/2);
  const icons=t['v2-icons'];for(let i=0;i<9;i++){const canvas=document.createElement('canvas');canvas.width=icons.width/3;canvas.height=icons.height/3;canvas.getContext('2d')!.drawImage(icons.image.data as CanvasImageSource,i%3*canvas.width,Math.floor(i/3)*canvas.height,canvas.width,canvas.height,0,0,canvas.width,canvas.height);this.urls['icon'+i]=this.fitArt(canvas,canvas.width,canvas.height,.09);}
  const nav=t['v2-navigation'];for(let i=0;i<9;i++)this.urls['nav'+i]=this.crop(nav,i%3*nav.width/3,Math.floor(i/3)*nav.height/3,nav.width/3,nav.height/3);
  const d=t['dungeon-ui-v2'];for(let i=0;i<4;i++)this.urls['dungeon'+i]=this.crop(d,38,[280,590,898,1190][i],390,260);
  const c=t['v2-controls'];const boxes=[[28,90,579,203],[646,90,590,203],[50,365,535,455],[637,510,605,180],[162,889,285,290],[572,948,674,180]];boxes.forEach((r,i)=>this.urls['control'+i]=this.crop(c,r[0],r[1],r[2],r[3]));
  const skills=t['v2-skills'];for(let i=0;i<9;i++)this.urls['ability'+i]=this.crop(skills,i%3*skills.width/3,Math.floor(i/3)*skills.height/3,skills.width/3,skills.height/3);this.urls.tree=this.urls.ability6;this.urls.material=this.urls.ability7;this.urls.ticket=this.urls.ability8;
  // Peach secondary button, round close, padlocks and star from the shared modal control sheet.
  const m=t['modal-controls-9'];if(m){const r:[string,number[]][]=[['peach',[452,155,349,143]],['roundClose',[84,496,262,267]],['lock',[910,494,236,262]],['unlock',[103,883,236,276]],['starIcon',[494,904,260,252]]];r.forEach(([k,b])=>this.urls[k]=this.crop(m,b[0],b[1],b[2],b[3]));}
  // Endless tower and daily mushroom illustrations (text-free crops of the approved concepts).
  const ai=t['v2-attribute-icons'];if(ai){const z=ai.width/7;for(let k=0;k<14;k++)this.urls['attr'+k]=this.crop(ai,(k%7)*z,Math.floor(k/7)*z,z,z);}const f=t['v2-feature-scenes'];if(f){this.urls.endlessArt=this.crop(f,0,0,f.width,f.height/2);this.urls.dailyArt=this.crop(f,0,f.height/2,f.width,f.height/2);}
 }
 private pruneActions(){const active=new Set(Array.from(this.root.querySelectorAll<HTMLElement>('[data-action]')).map(n=>n.dataset.action!));this.actions.forEach((_,id)=>{if(!active.has(id))this.actions.delete(id);});}
 private img(name:string,cls='',alt=''){return `<img class="${cls}" src="${this.urls[name]||''}" alt="${esc(alt)}" draggable="false">`;}
 private button(text:string,fn:()=>void,cls='',disabled=false,label=''){const id=String(++this.serial);this.actions.set(id,fn);return `<button type="button" data-action="${id}" class="v2-button ${cls}" ${disabled?'disabled':''} ${label?`aria-label="${esc(label)}"`:''}>${text}</button>`;}
 private face(id:number,cls=''){return this.img(['hero-knight','hero-mage','hero-priest','hero-archer'][id],'face '+cls,NAMES[id]);}
 private resource(icon:number,value:unknown){return `<span class="resource">${this.img('icon'+icon)}<b>${esc(value)}</b></span>`;}
 private wallet(stamina=true){const b=this.port.model();return `<header class="wallet">${this.resource(6,b.gold)}${stamina?this.resource(8,b.dungeon.stamina+'/120'):''}</header>`;}
 private nav(selected:Page){return `<nav class="v2-nav" aria-label="主导航">${(['hero','recruit','adventure','bag','dungeon'] as Page[]).map((p,i)=>this.button(this.img('nav'+i)+`<b>${['英雄','招募','冒险','背包','副本'][i]}</b>`,()=>this.go(p),selected===p?'selected':'quiet')).join('')}</nav>`;}
 setPage(p:Page){this.page=p;this.draw();}
 private go(p:Page){this.close();this.page=p;this.port.navigate(p);this.draw();}
 private run(fn:(b:SquadBattleModel)=>string|null,next?:()=>void){const error=this.port.mutate(fn);if(error){this.toast(error);return false;}next?.();return true;}
 toast(text:string){const n=this.root.querySelector('.v2-toast')!;n.textContent=text;n.classList.add('visible');clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>n.classList.remove('visible'),2600);}
 private close(){this.modal.innerHTML='';}
 private plate(title:string){return `<span class="plate"><i>✦</i><span>${esc(title)}</span><i>✦</i></span>`;}
 private hint(){return `<p class="outside-hint">${ico('leaf')}点击空白处关闭${ico('leaf','mirror')}</p>`;}
 private popup(title:string,body:string,actions='',size='medium'){
  const oldFocus=document.activeElement as HTMLElement;const full=size.indexOf('fullscreen')>=0;
  const head=full?`<header class="dialog-head celebrate">${LAUREL}<h2>${esc(title)}</h2>${LAUREL.replace('class="laurel"','class="laurel mirror"')}</header>`:`<header class="dialog-head"><h2 class="plaque">${this.plate(title)}</h2>${this.button('×',()=>{this.close();oldFocus?.focus();},'close',false,`关闭${title}`)}</header>`;
  this.modal.innerHTML=`<div class="v2-scrim ${full?(size.indexOf('rewards')>=0?'dark warm':'dark'):''}"><section class="v2-dialog ${size}" role="dialog" tabindex="-1" aria-modal="true" aria-label="${esc(title)}">${head}<div class="dialog-body">${body}</div>${actions?'<footer class="dialog-actions">'+actions+'</footer>':''}</section>${this.hint()}</div>`;
  const shade=this.modal.firstElementChild!;shade.addEventListener('click',e=>{if(e.target===shade||(e.target as HTMLElement).closest('.outside-hint'))this.close();});this.modal.querySelector<HTMLElement>('[role=dialog]')?.focus();
 }
 private info(title:string,text:string,confirm?:()=>void){this.confirm(title,esc(text),confirm);}
 private confirm(title:string,html:string,confirm?:()=>void){this.popup(title,`<div class="info-pad">${html}</div>`,confirm?this.button('取消',()=>this.close(),'peach')+this.button('确定',()=>{this.close();confirm();}):'','small');}
 private row(name:string,value:unknown,icon=''){return `<div class="stat-row"><span>${icon?ico(icon):''}${esc(name)}</span><b>${value}</b></div>`;}
 private arrow(before:unknown,after:unknown){return `<span class="change">${before}<i>➜</i><em>${after}</em></span>`;}
 private section(title:string){return `<h3 class="section-title"><span>${ico('leaf')}${esc(title)}</span></h3>`;}
 private divider(){return '<div class="ornament-line"><i>✦</i></div>';}
 private gear(g:Gear|null,slot=0,extra=''){return `<div class="gear-tile ${g?'':'empty'}" style="--quality:${g?Q[g.quality]:'#c4b6a6'}">${g?this.img('icon'+g.slot):'<span class="empty-slot-symbol">＋</span>'}${g?`<b class="gear-level">Lv.${g.level}</b>${g.locked?this.img('lock','gear-lock'):''}`:''}${extra}</div>`;}
 private roleBadge(id:number){return `<i class="role-badge r${id}">${ico(ROLE_ICONS[id])}</i>`;}
 private starRow(n:number){return `<span class="star-row" aria-label="${n}星">${'<i class="on">★</i>'.repeat(n)}${'<i>★</i>'.repeat(Math.max(0,5-n))}</span>`;}
 private heroCard(id:number,o:{rarity?:number;tag?:string;deployed?:boolean}={}){const b=this.port.model(),h=b.heroes[id],owned=b.owns(id);return `<div class="hero-card ${owned?'':'locked'}" title="${NAMES[id]}" style="--quality:${Q[o.rarity===undefined?[4,3,2,2][id]:o.rarity+2]}">${this.roleBadge(id)}${o.tag?`<em class="card-tag ${o.tag==='NEW'?'new':'dup'}">${o.tag}</em>`:''}<div class="portrait">${this.face(id)}${o.deployed?'<span class="deployed">已上阵</span>':''}${owned?'':this.img('lock','card-lock')}</div><span class="sr">${NAMES[id]}</span><b>Lv.${h.level}</b>${this.starRow(h.stars)}</div>`;}
 private reward(icon:number,n:number,label:string,quality=2){return `<div class="reward" style="--quality:${Q[quality]}">${this.img(label==='强化石'?'material':'icon'+icon)}<b>×${n}</b><small>${esc(label)}</small></div>`;}
 private gearReward(slot:number,quality:number,level:number){return `<div class="reward" style="--quality:${Q[quality]}">${this.img('icon'+slot)}<b>Lv.${level}</b><small>${QUALITY_NAMES[quality]}${EQUIPMENT_PARTS[slot]}</small></div>`;}
 private rewardItems(r:OfflineReward|null){return this.reward(6,r?.gold||0,'金币',4)+this.reward(7,r?.experience.reduce((n,v)=>n+v,0)||0,'英雄经验')+(r?.equipment.map(g=>this.gear(g)).join('')||'');}
 private rewardList(b:SquadBattleModel){return this.rewardItems(b.offline);}
 private rewardViewport(items:string,cls=''){return `<div class="reward-scroll ${cls}" tabindex="0" aria-label="奖励列表，可上下滑动"><div class="five-grid">${items||'<p class="empty-message">暂无奖励</p>'}</div></div>`;}
 private dungeonRewards(id:number,difficulty:number){const r=dungeonReward(id,difficulty);let items='';if(r.gold)items+=this.reward(6,r.gold,'金币');if(r.experience)items+=this.reward(7,r.experience,'每位英雄经验');if(r.materials)items+=this.reward(7,r.materials,'强化石');if(r.gear)items+=[0,1,3].map((s,i)=>this.gearReward(s,[3,2,1][i],r.level)).join('');return items;}
 draw(){this.inSecondary=false;this.root.classList.toggle('battle-mode',this.page==='adventure'||this.page==='dungeon'&&!!this.port.model().dungeon.run&&this.port.battle()!==this.port.model());this.backdrop.style.backgroundImage=`url("${this.urls.scene0}")`;this.backdrop.style.display='none';this.content.innerHTML=this.page==='adventure'?this.adventure():this.page==='hero'?this.hero():this.page==='bag'?this.bag():this.page==='recruit'?this.recruit():this.dungeons();}
 private adventure(){const b=this.port.battle();return `<div class="battle-hud">${this.wallet()}${this.button('☰',()=>this.settings(),'menu quiet')}<div class="stage-heading"><h1>${this.page==='dungeon'?DUNGEONS[this.port.model().dungeon.run!.id].name:'镇外森林'}</h1><b data-live="wave">第${b.wave}波</b><div class="checkpoint"><i></i><i></i><i></i><i></i><i></i>⚑</div><small data-live="checkpoint">下一检查点 · 第${Math.ceil(b.wave/10)*10}波</small></div><div class="turn-order"><b>行动顺序</b>${b.order.map(i=>`<span class="turn-portrait" data-turn="${i}">${i<3?this.face(b.formation[i]):this.img('monster'+b.enemies[i-3].kind)}</span>`).join('<span class="turn-arrow">➜</span>')}</div><div class="battle-tools">${this.button(this.port.speed()+'×',()=>{this.port.setSpeed();this.draw();},'quiet')}${this.button(this.img('nav7')+'<small>统计</small>',()=>this.statistics(),'quiet')}${this.button(this.img('nav8')+'<small>自动技能</small>',()=>{const before=b.autoSkill;b.autoSkill=!before;const error=this.port.mutate(()=>null);if(error){b.autoSkill=before;this.toast(error);}this.draw();},'quiet '+(b.autoSkill?'on':''))}</div><div class="field-actions">${this.button(this.img('nav5')+'阵型',()=>this.formation(),'quiet')}${this.page==='adventure'?this.button(this.img('nav6')+'挂机收益',()=>this.offline(),'quiet'):this.port.model().dungeon.run?.receipt?this.button('查看结算',()=>this.result(),'quiet'):this.button('离开战斗',()=>{this.port.leave();this.draw();},'quiet')}</div><div class="skill-bar">${b.formation.map((id,i)=>{const h=b.heroes[id];return `<section class="party-card"><header><span class="party-portrait">${this.face(id)}</span><div><b>${NAMES[id]}</b><span class="party-tags"><i>Lv.${h.level}</i><i class="role-pill r${id}">${ico(id===0?'shield':ROLE_ICONS[id])}${ROLES[id]}</i></span><div class="health-track"><i data-hp="${id}"></i></div><small data-hp-label="${id}">${h.hp}/${b.stats(id).hp}</small><small data-shield="${id}"></small></div></header><div class="active-skills">${[0,2].map((skill,j)=>this.button((b.unlocked(id,skill)?this.skillIcon(id,skill):'<span class="locked-skill-icon">'+ico('lock')+'</span>')+`<span data-cooldown="${id}-${j}"></span><small>${b.unlocked(id,skill)?SKILL_NAMES[id][skill]:'待解锁'}</small>`,()=>{if(!b.requestSkill(i,j))this.toast(b.unlocked(id,skill)?'技能冷却中或英雄已阵亡':SKILL_LEVELS[skill]+'级解锁');else {const error=this.port.mutate(()=>null);if(error){if(j)h.queued2=false;else h.queued=false;this.toast(error);}else this.toast('已加入释放队列');}},'skill-button '+(b.unlocked(id,skill)?'':'unavailable'))).join('')}</div></section>`;}).join('')}</div>${this.nav(this.page==='dungeon'?'dungeon':'adventure')}</div>`;}
 private skillIcon(id:number,index:number){const b=this.port.model();return this.img('ability'+(!b.unlocked(id,index)?3:index%2===1?1:id===0?index===0?0:2:id===2?5:id===1?4:2));}
 private settings(){const b=this.port.battle();this.popup('战斗设置','<div class="info-pad">战斗倍速不影响体力恢复与挂机收益。</div>',this.button(b.paused?'继续战斗':'暂停战斗',()=>{b.paused=!b.paused;this.close();})+(this.page==='dungeon'?this.button('结束挑战',()=>{this.close();this.port.end();},'peach'):''),'small');}
 private statistics(){const b=this.port.battle();this.popup('战斗统计',this.section('输出与治疗')+b.formation.map(i=>this.row(NAMES[i],b.heroes[i].damage+' / '+b.heroes[i].healing,ROLE_ICONS[i])).join('')+this.row('承受伤害',b.received,'shield')+this.row('战斗时长',Math.floor(b.elapsed)+'秒','clock'));}
 private hero(){const b=this.port.model(),id=this.selected,h=b.heroes[id],s=b.stats(id),owned=b.owns(id);return `<div class="page hero-page" style="--scene:url('${this.urls.scene1}')">${this.wallet(false)}<div class="hero-tabs">${HERO_CONFIG.map((c,i)=>this.button(`<span class="tab-portrait">${this.face(i)}</span><b>${NAMES[i]}</b>`,()=>{this.selected=i;this.draw();},i===id?'selected':'quiet')).join('')}</div><div class="hero-stage" style="background-image:url('${this.urls.scene1}')"><h1>${NAMES[id]} · Lv.${h.level}</h1><div class="hero-identity"><div class="stars">${this.starRow(h.stars)}${this.button(ico('star'),()=>this.star(),'star-button',false,'英雄升星')}</div><p class="roles"><span>${this.attributeIcon(id===0?'shield':id===2?'cross':'burst')}${ROLES[id]}</span></p></div><div class="equipment-left">${[0,1,2].map(slot=>this.button(this.gear(b.equipment(id)[slot],slot)+`<small>${EQUIPMENT_PARTS[slot]}</small>`,()=>this.equipmentSlot(slot),'equipment-slot')).join('')}</div><i class="hero-shadow"></i>${this.face(id,'hero-figure')}<div class="equipment-right">${[3,4,5].map(slot=>this.button(this.gear(b.equipment(id)[slot],slot)+`<small>${EQUIPMENT_PARTS[slot]}</small>`,()=>this.equipmentSlot(slot),'equipment-slot')).join('')}</div>${this.button(ico('people')+'编队',()=>this.formation(),'quiet formation-link')}</div><div class="experience"><small>经验 ${h.experience}/${upgradeCost(h.level)}</small><div class="exp-track"><i style="width:${Math.min(100,h.experience/upgradeCost(h.level)*100)}%"></i></div>${this.button(RESET_ICON,()=>this.resetExperience(),'flat experience-reset',!owned||h.level===1,'经验重置')}</div><div class="page-actions">${this.button('一键换装',()=>this.run(m=>m.autoEquip(id),()=>this.draw()),'',!owned)}${this.button('升级',()=>this.run(m=>m.upgrade(id),()=>this.draw()),'',!owned||h.level>=100)}</div><section class="cream-card skills-card"><h3 class="card-title">技能</h3><div class="hero-skills">${[0,1,2,3].map(i=>this.button(`<small class="kind">${i%2?'被动':'主动'}</small>${b.unlocked(id,i)?'<span class="hero-skill-art">'+this.skillIcon(id,i)+'</span>':'<span class="locked-skill-icon">'+ico('lock')+'</span>'}${b.unlocked(id,i)?'<b>'+SKILL_NAMES[id][i]+'</b>':'<small class="unlock-level">'+SKILL_LEVELS[i]+'级解锁</small>'}`,()=>this.skill(i),'flat '+(b.unlocked(id,i)?'':'unavailable'),false,SKILL_NAMES[id][i])).join('')}<i class="skill-divider"></i>${this.button(this.img('tree')+'<b>天赋树</b><small>'+b.talentPoints(id)+'点</small>',()=>this.talents(),'flat tree-button')}</div></section><section class="cream-card attributes"><h3 class="card-title">英雄属性</h3>${this.heroAttributes(id)}</section>${this.nav('hero')}</div>`;}
 private resetExperience(){const b=this.port.model(),id=this.selected,h=b.heroes[id],refund=Array.from({length:h.level-1},(_,i)=>upgradeCost(i+1)).reduce((a,v)=>a+v,0);this.confirm('经验重置',`将${NAMES[id]}重置为 Lv.1，返还 <b>${refund}</b> 已投入经验。<br><small>天赋将一并重置，星级和装备保留。</small>`,()=>this.run(m=>m.resetHeroExperience(id),()=>{this.close();this.draw();}));}
 private statIcon(k:number,fallback:string){const u=this.urls['attr'+k];return u?`<i class="attribute-icon stat-glyph" style="-webkit-mask-image:url('${u}');mask-image:url('${u}')" aria-hidden="true"></i>`:this.attributeIcon(fallback);}
 private attributeIcon(name:string){return `<svg class="attribute-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]}"/></svg>`;}
 private heroAttributes(id:number){const b=this.port.model(),s=b.stats(id),c=b.combatStats(id),pct=(v:number)=>Math.round(v*100)+'%';const attrs:[string,unknown,string][]=[['生命',s.hp,'heart'],['攻击',s.attack,'sword'],['防御',s.defense,'shield'],['移速',s.speed,'speed'],['暴击率',pct(c.critChance),'burst'],['暴击伤害',pct(c.critDamage),'burst'],['连击率',pct(c.comboChance),'refresh'],['破甲率',pct(c.armorPen),'shield'],['冷却缩减',pct(c.cooldownReduction),'hourglass'],['治疗加成',pct(c.healingBonus),'cross'],['护盾加成',pct(c.shieldBonus),'shield'],['普攻伤害',pct(c.basicBonus),'blades'],['技能伤害',pct(c.skillBonus),'fire'],['闪避率',pct(c.dodgeChance),'speed']];return `<div class="hero-attribute-grid">${attrs.map(([name,value,icon],i)=>`<div style="grid-column:${i<7?1:2};grid-row:${i%7+1}" title="${name}：当前战斗数值"><div class="stat-row"><span>${this.statIcon(i,icon)}${name}${name==='破甲率'?this.button('?',()=>this.info('破甲率','攻击时忽略目标对应比例的护甲；同时作用于普通攻击和伤害技能。当前测试上限75%。'),'flat attribute-help',false,'破甲率说明'):''}</span><b>${value}</b></div></div>`).join('')}</div>`;}

 private star(){const b=this.port.model(),id=this.selected,p=b.starPreview(id);if(!p){this.info('英雄升星','请先招募该英雄');return;}const max=p.stars>=5;this.popup('英雄升星',`<div class="item-heading"><div class="portrait-tile" style="--quality:${Q[[4,3,2,2][id]]}">${this.face(id)}</div><div><h3>${NAMES[id]}</h3><p class="star-change">${'★'.repeat(p.stars)}<i>➜</i>${max?'已满星':'★'.repeat(p.stars+1)}</p></div></div>${this.divider()}`+this.section('提升预览')+this.row('生命',this.arrow(p.before.hp,p.after.hp),'heart')+this.row('攻击',this.arrow(p.before.attack,p.after.attack),'sword')+this.row(SKILL_NAMES[id][0]+'效果',this.arrow(p.before.power,p.after.power),'shield')+this.divider()+this.section('升星消耗')+`<div class="cost-card"><div class="portrait-tile small" style="--quality:${Q[[4,3,2,2][id]]}">${this.face(id)}<b>×${p.cost}</b></div><div><h3>${NAMES[id]}份数</h3><p>持有 <em class="${p.available>=p.cost?'':'short'}">${p.available}</em> 份 / 消耗 ${p.cost} 份</p></div></div>`,this.button(max?'已满星':'升星',()=>this.run(m=>m.starUp(id),()=>{this.draw();this.star();}),'wide',max||p.available<p.cost));}
 private skill(index:number){const b=this.port.model(),id=this.selected,s=b.stats(id),passive=index%2===1;const descriptions=[['为自己施加护盾，抵挡敌人的伤害。','提升自身防御。','挥盾打击攻击最高的敌人。','强化两个主动技能的效果。'],['向随机敌人投出火焰。','强化主动技能效果。','引爆生命比例最低的敌人。','强化两个主动技能的效果。'],['恢复生命比例最低的队友。','提升主动治疗效果。','为伤势最重的队友施加强效治疗。','强化两个主动技能的效果。'],['射出一箭，攻击随机敌人。','提升普通攻击伤害。','瞄准生命比例最低的敌人射击。','强化两个主动技能的效果。']];const power=Math.round(s.power*(index===2?1.4:1));this.popup('技能详情',`<div class="item-heading"><div class="skill-preview">${this.skillIcon(id,index)}</div><div><h3>${SKILL_NAMES[id][index]}</h3><p class="pill">${passive?'被动':'主动'} · ${b.unlocked(id,index)?'已解锁':SKILL_LEVELS[index]+'级解锁'}</p></div></div>${this.divider()}`+this.section('技能属性')+this.row(passive?'解锁等级':id===2?'治疗量':id===0&&index===0?'护盾值':'技能效果',`<em>${passive?'Lv.'+SKILL_LEVELS[index]:power}</em>`,passive?'star':id===2?'heart':id===0?'shield':'fire')+this.row(passive?'生效方式':'冷却',passive?'自动生效':`<em class="blue">${index===0?s.cooldown:b.secondCooldown(id)}秒</em>`,'clock')+this.section('技能描述')+`<div class="info-pad">${descriptions[id][index]}</div>`);}
 private treeLayout(){const left=[[25,86],[13,70],[28,55],[14,39],[26,23]],right=left.map(([x,y])=>[100-x,y]);return Array.from({length:15},(_,i)=>i<5?[50,88-i*18.5]:i<10?left[i-5]:right[i-10]);}
 private talents(selected=0){const b=this.port.model(),id=this.selected;if(!b.owns(id)){this.info('天赋树','请先招募该英雄');return;}const tree=b.interfaceProgress.tree[id],pos=this.treeLayout();
  const icons=['sparkle','shield','fire','heart','refresh','heart','shield','heart','shield','heart','sword','fire','sword','fire','sword'];
  const branch=(o:number)=>pos.slice(o,o+5).map(([x,y],k)=>k?`L${x} ${y}`:`M50 ${y+3}Q${(50+x)/2} ${y+4} ${x} ${y}`).join(' ').replace(/L/g,'L');
  const leaves=pos.map(([x,y],i)=>i%2?`<ellipse cx="${x+(x<50?6:-6)}" cy="${y-6}" rx="2.4" ry="1.1" transform="rotate(${x<50?-35:35} ${x+(x<50?6:-6)} ${y-6})"/>`:'').join('');
  this.popup('天赋树',`<div class="talent-wallet">${this.face(id)}<b>${NAMES[id]}</b><i></i>可用天赋点 <em>${b.talentPoints(id)}</em></div><div class="talent-tree"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path class="trunk" d="M50 98 L50 12"/><path class="branch" d="${branch(5)}"/><path class="branch" d="${branch(10)}"/><g class="leaves">${leaves}</g></svg>${pos.map(([x,y],i)=>{const ready=TREE_NODES[i].parent<0||tree[TREE_NODES[i].parent];return this.button(ico(icons[i])+(tree[i]?'<b>1/1</b>':''),()=>this.talents(i),'talent-node '+(tree[i]?'learned ':ready?'ready ':'')+(i===selected?'current':'')+`" style="left:${x}%;top:${y}%`,false,TREE_NODES[i].name);}).join('')}</div><div class="talent-info"><div><h3>${TREE_NODES[selected].name}</h3><p>${TREE_NODES[selected].description}</p></div><i></i><b>${tree[selected]?'已学习':'消耗 <em>1</em> 点'}</b></div>`,this.button('重置天赋',()=>this.info('重置天赋','返还该英雄已投入的全部天赋点？',()=>this.run(m=>m.resetTreeTalents(id),()=>this.talents(selected))),'peach')+this.button('学习天赋',()=>this.run(m=>m.trainTreeTalent(id,selected),()=>this.talents(selected))),'large');}
 private equipmentSlot(slot:number){if(!this.port.model().owns(this.selected)){this.info('装备穿戴','请先招募该英雄');return;}const g=this.port.model().equipment(this.selected)[slot];if(g)this.detail(g.id);else this.picker(slot);}
 private filters(update:()=>void){return `<div class="filter-row">${this.button(ico('filter','outline-filter')+'筛选',()=>{this.popup('品质筛选',`<div class="filter-options">${this.button('全部品质',()=>{this.quality=-1;update();},'quiet')+QUALITY_NAMES.map((q,i)=>this.button(q,()=>{this.quality=i;update();},this.quality===i?'':'quiet')).join('')}</div>`,'','small');},'quiet')}${this.button('品质 '+ico('sort',this.reverse?'sort-direction ascending':'sort-direction')+ico('chevron','outline-chevron'),()=>{this.reverse=!this.reverse;update();},'quiet')}</div>`;}
 private filtered(slot=this.part){return this.port.model().inventory.filter(g=>(slot<0||g.slot===slot)&&(this.quality<0||g.quality===this.quality)).slice().sort((a,b)=>(b.quality-a.quality)*(this.reverse?-1:1)||b.level-a.level||b.id-a.id);}
 private picker(slot:number){const b=this.port.model(),items=this.filtered(slot).filter(g=>b.owner(g.id)<0);this.popup('装备选择',this.filters(()=>this.picker(slot))+`<div class="equipment-scroll"><div class="five-grid">${items.map(g=>this.button(this.gear(g),()=>this.detail(g.id),'flat')).join('')}${Array.from({length:Math.max(0,20-items.length)},()=>'<div class="gear-tile empty"></div>').join('')}</div></div><div class="part-tabs labeled">${[-1,0,3,4,5,1,2].map(i=>this.button((i<0?ico('grid','outline-grid'):this.img('icon'+i))+`<small>${i<0?'全部':EQUIPMENT_PARTS[i]}</small>`,()=>this.picker(i),i===slot?'selected':'flat')).join('')}</div>`,'','large');}
 private gearRows(g:Gear,next?:Gear,random=false){const primary=gearPrimary(g),s=gearStats(g),after=next?gearStats(next):s;const rows=(['hp','attack','defense','power'] as const).filter(k=>(random?k!==primary:k===primary)&&s[k]>0).map(k=>this.row(GEAR_ATTRIBUTE_NAMES[k],next&&(!random||g.level%10===9)?this.arrow(s[k],after[k]):s[k],{hp:'heart',attack:'sword',defense:'shield',power:'sparkle'}[k])).join('');const affixes=random?COMBAT_KEYS.filter(k=>g.combat?.[k]).map(k=>this.row(COMBAT_LABELS[k],next&&g.level%10===9?this.arrow(Math.round(g.combat![k]!*10000)/100+'%',Math.round((next.combat?.[k]||0)*10000)/100+'%'):Math.round(g.combat![k]!*10000)/100+'%','sparkle')).join(''):'';return rows+affixes||'<div class="info-pad compact">无</div>';}
 private detail(id:number){const b=this.port.model(),g=b.inventory.find(g=>g.id===id);if(!g)return;const owner=b.owner(id);this.popup('装备详情',`<div class="item-heading">${this.gear(g)}<div><h3>${gearName(g)}</h3><p class="quality-pill" style="--tone:${QUALITY_TEXT[g.quality]}">${QUALITY_NAMES[g.quality]} · ${EQUIPMENT_PARTS[g.slot]}</p><p class="pill">Lv.${g.level}${g.enhancement?' · 强化 +'+g.enhancement:''}</p></div>${this.button(this.img(g.locked?'lock':'unlock'),()=>this.run(m=>m.toggleLock(id),()=>this.detail(id)),'flat lock-button',false,g.locked?'解除锁定':'锁定装备')}</div>${this.divider()}`+this.section('基础属性')+this.gearRows(g)+this.section('随机属性')+this.gearRows(g,undefined,true)+`<h3 class="section-title effect"><span>${ico('sparkle')}装备效果</span></h3><div class="effect-line">${g.effects?.length?g.effects.map(e=>ico('refresh')+(e==='attack'?'攻击力':'最大生命值')+' 提高<em>5%</em>').join('<br>'):'无'}</div><small class="equip-owner">${owner>=0?'穿戴中：'+NAMES[owner]:'穿戴给：'+NAMES[this.selected]}</small>`,this.button('强化',()=>{this.close();this.upgradePage(id);},'peach')+this.button(owner>=0?'卸下':'穿戴',()=>this.run(m=>m.equip(owner>=0?owner:this.selected,owner>=0?null:id,g.slot),()=>{this.close();this.draw();})) );}
 private upgradePage(id:number){const b=this.port.model(),g=b.inventory.find(g=>g.id===id);if(!g)return;this.inSecondary=true;this.root.classList.remove('battle-mode');const breakthrough=g.level%10===9,cost=(g.quality+1)*(breakthrough?15:4),gold=g.level*(breakthrough?100:30),after=gearUpgradePreview(g);const need=(have:number,n:number)=>`<b><em class="${have>=n?'':'short'}">${have}</em>/${n}</b>`;this.content.innerHTML=`<div class="secondary upgrade-page"><div class="forge-scene" style="background-image:url('${this.urls.scene4}')">${this.wallet(false)}<h1 class="title-plaque plaque">${this.plate('装备强化')}</h1><div class="forge-item">${this.gear(g)}<div><h2>${gearName(g)}</h2><p class="quality-pill" style="--tone:${QUALITY_TEXT[g.quality]}">${QUALITY_NAMES[g.quality]} · ${EQUIPMENT_PARTS[g.slot]}</p></div></div>${this.img('icon'+g.slot,'forge-weapon')}</div><div class="upgrade-body"><h1 class="level-preview">${g.level>=100?'Lv.100 · 已达上限':'Lv.'+g.level+' <i>➜</i> <em>Lv.'+(g.level+1)+'</em>'}</h1>${this.section('基础属性')+this.gearRows(g,after)+this.section('随机属性')+this.gearRows(g,after,true)}${breakthrough?'<p class="breakthrough-note"><span>◇　突破提升基础属性与随机属性　◇</span></p>':''}<div class="upgrade-costs"><div><span class="cost-icon">${this.img('material')}</span>${need(b.materials,cost)}</div><div><span class="cost-icon">${this.img('icon6')}</span>${need(b.gold,gold)}</div>${this.button(g.level>=100?'已满级':breakthrough?'突破':'升级',()=>this.run(m=>m.upgradeGear(id),()=>this.upgradePage(id)),'',g.level>=100)}</div>${this.button('关闭',()=>this.draw(),'secondary-close')}</div></div>`;}
 private bag(){const b=this.port.model(),items=this.filtered(),cap=Math.max(b.interfaceProgress.capacity,b.inventory.length),cost=500*(1+Math.floor((b.interfaceProgress.capacity-200)/50));return `<div class="page bag-page" style="--scene:url('${this.urls.scene5}')">${this.wallet(false)}<div class="main-tabs">${['装备','材料','道具'].map((t,i)=>this.button(t,()=>{this.category=i;this.draw();},i===this.category?'selected':'quiet')).join('')}</div>${this.category===0?`<div class="part-tabs">${[-1,0,1,2,3,4,5].map(i=>this.button(i<0?ico('grid','outline-grid'):this.img('icon'+i),()=>{this.part=i;this.draw();},i===this.part?'selected':'quiet',false,i<0?'全部':EQUIPMENT_PARTS[i])).join('')}</div>${this.filters(()=>{this.close();this.draw();})}`:''}<div class="bag-scroll cream-card"><div class="five-grid">${this.category===0?items.map(g=>this.button(this.gear(g),()=>this.detail(g.id),'flat')).join('')+Array.from({length:Math.max(0,25-items.length)},()=>'<div class="gear-tile empty"></div>').join(''):this.category===1?this.reward(7,b.materials,'强化石'):'<p class="empty-message">暂无道具</p>'}</div></div><div class="bag-footer"><b>容量 ${b.inventory.length}/${cap}</b>${this.button(ico('plus')+this.img('icon6')+cost+' 扩容',()=>this.confirm('提示',`是否消耗 ${this.img('icon6','inline-icon')} <b>${cost}</b><br>将背包容量扩充至 <b>${b.interfaceProgress.capacity+50}</b> 格？<small>当前容量 ${b.inventory.length}/${cap}</small>`,()=>this.run(m=>m.expandBag(),()=>this.draw())),'quiet expand-button')}${this.button('批量分解',()=>this.salvage(),'salvage-button')}</div>${this.nav('bag')}</div>`;}
 private salvage(selected=new Set<number>()){const b=this.port.model(),items=b.inventory.filter(g=>!g.locked&&b.owner(g.id)<0),preview=b.salvagePreview([...selected]);const redraw=()=>this.salvage(selected);this.popup('装备分解',`<p class="label-line">按品质选择</p><div class="quality-checks">${QUALITY_NAMES.map((q,i)=>{const subset=items.filter(g=>g.quality===i),on=subset.length>0&&subset.every(g=>selected.has(g.id));return this.button(`<i class="box ${on?'on':''}">${on?ico('check'):''}</i><span style="color:${QUALITY_TEXT[i]}">${q}</span>`,()=>{const all=subset.every(g=>selected.has(g.id));subset.forEach(g=>all?selected.delete(g.id):selected.add(g.id));redraw();},'flat check-option');}).join('')}</div><p class="lock-note">${ico('lock')}锁定和已穿戴装备不参与分解</p><div class="list-heading"><b>可分解装备</b><span>已选择 <em>${selected.size}件</em></span></div><div class="equipment-scroll salvage-scroll"><div class="five-grid">${items.map(g=>this.button(this.gear(g,g.slot,selected.has(g.id)?`<span class="checked">${ico('check')}</span>`:''),()=>{selected.has(g.id)?selected.delete(g.id):selected.add(g.id);redraw();},'flat')).join('')}</div></div><div class="material-line"><b>可获得材料</b><span>${this.img('material')}×${preview.materials}</span></div>`,this.button('分解装备',()=>this.info('确认分解','分解后装备无法恢复，是否分解选中的'+selected.size+'件装备？',()=>this.run(m=>m.salvage([...selected]),()=>{this.draw();this.rewards(this.reward(7,preview.materials,'强化石'));})),'',!selected.size)+`<small class="warn">${ico('warn')}分解后无法恢复</small>`,'large');}
 private recruit(){const b=this.port.model(),r=b.recruitment,p=r.pity[this.pool],left=RECRUIT_CONFIG.legendPity-p.legend;const cast=this.pool?[[3,'c-back'],[2,'c-left'],[0,'c-right'],[1,'c-front']]:[[3,'c-left'],[1,'c-back'],[2,'c-right'],[0,'c-front']];return `<div class="page recruit-page ${this.pool?'up':'normal'}" style="background-image:url('${this.urls['scene'+(this.pool?3:2)]}')"><header class="wallet">${this.button('☰',()=>this.info('招募说明','常驻券与UP券分别使用，两池保底独立计算。'),'menu quiet')}${this.resource(6,b.gold)}<span class="resource ticket-resource">${this.ticketArt()}<b>${this.pool?b.interfaceProgress.upTickets:r.tickets}</b></span></header><div class="main-tabs">${['常驻招募','UP招募'].map((t,i)=>this.button(t,()=>{this.pool=i;this.draw();},this.pool===i?'selected':'quiet')).join('')}</div><div class="recruit-banner"><h1>${LAUREL}<span>${this.pool?'星光邀约':'冒险伙伴'}</span>${LAUREL.replace('class="laurel"','class="laurel mirror"')}</h1><p class="ribbon">${this.pool?'艾琳概率提升':'永久开放'}</p></div><div class="recruit-cast">${cast.map(([id,cls])=>this.face(id as number,'cast '+cls)).join('')}${this.pool?'<span class="up-badge">艾琳<b>UP</b></span>':''}</div><div class="recruit-bottom"><div class="pity-panel"><span class="crown">${ico('crown')}</span><div><p>当前抽数 <em>${p.legend}</em>/${RECRUIT_CONFIG.legendPity}</p><div class="exp-track"><i style="width:${p.legend/RECRUIT_CONFIG.legendPity*100}%"></i></div><small>距离传说保底还需<em>${left}</em>抽</small></div></div><div class="pool-links">${this.button(ico('book')+'卡池详情',()=>this.poolDetails(),'quiet')}${this.button(ico('list')+'招募记录',()=>this.results(r.history.filter(x=>x.pool===this.pool).slice(-10),true),'quiet')}</div><div class="page-actions">${this.drawButtons()}</div></div>${this.nav('recruit')}</div>`;}
 private ticketArt(){return `<svg class="ticket-art ${this.pool?'up-ticket':''}" viewBox="0 0 48 48" aria-hidden="true"><path d="M12 5h29l-6 11a5 5 0 0 0-4 8l-8 18H3l7-18a5 5 0 0 0 3-9z" fill="currentColor" stroke="#965220" stroke-width="2.5" stroke-linejoin="round"/><path d="M16 10h18L22 36H10z" fill="#fff0cf"/><path d="m24 14 1.2 5 5 .6-4.5 3.4-.3 5.3-3.4-3.4-5 1.5 2.4-5-1.3-4.3 4.2.5z" fill="currentColor"/><path d="m10 29 15 2M13 13l17 3" stroke="#965220" stroke-width="1.5" opacity=".55"/></svg>`;}
 private ticketChip(n:number){return `<small class="ticket-chip">${this.ticketArt()}×${n}</small>`;}
 private drawButtons(peach=false){return [1,10].map(n=>this.button(`<b>招募${n===1?'一次':'十次'}</b>${this.ticketChip(n)}`,()=>{if(this.run(m=>m.recruitPool(this.pool,n))){this.draw();this.results(this.port.model().recruitment.last);}},peach&&n===1?'peach':'')).join('');}
 private poolDetails(){const up=this.pool===1;this.popup(up?'UP池详情':'常驻池详情',`<p class="pool-name">${up?'星光邀约 · 艾琳概率提升':'冒险伙伴 · 永久开放'}</p>`+this.section('卡池内容')+`<div class="pool-heroes">${(up?[1,0,2,3]:[0,1,2,3]).map(i=>`<div class="portrait-tile" style="--quality:${Q[[4,3,2,2][i]]}">${this.face(i)}${up&&i===1?'<span class="up-mark">UP</span>':''}<small>${NAMES[i]}</small></div>`).join('')}</div>`+this.section('抽取概率')+[['稀有','star','#3b8fe0','75%'],['史诗','crown','#9a4fd0','20%'],['传说','crown','#e6a514','5%']].map(([q,icon,color,v])=>`<div class="stat-row rate"><span><i style="color:${color}">${ico(icon)}</i>${q}</span><b>${v}</b></div>`).join('')+this.section('规则说明')+`<ul class="rules">${(up?['传说必得艾琳，其余品质艾琳概率62.5%。','UP池与常驻池保底独立计算。']:['四位英雄等概率出现。','常驻池与UP池保底独立计算。']).concat(['10抽至少史诗，30抽必得传说。','单抽与十连共享本池保底。']).map(t=>`<li>${t}</li>`).join('')}</ul>`);}
 private results(rows:RecruitResult[],history=false){if(!rows.length){this.info('招募记录','暂无记录');return;}const one=rows.length===1,b=this.port.model();this.popup(history?'招募记录':'招募结果',`<p class="result-sub">本次招募获得<em>${rows.length}</em>位英雄</p><div class="result-cards ${one?'single':'five-grid'}">${rows.map(r=>this.heroCard(r.hero,{rarity:r.rarity,tag:r.fresh?'NEW':'重复'})).join('')}</div><p class="ticket-left">${this.ticketArt()}剩余<b>${this.pool?b.interfaceProgress.upTickets:b.recruitment.tickets}</b></p>`,history?'':this.drawButtons(true),'fullscreen results-screen');}
 private lineup(){const b=this.port.model();return `<div class="lineup">${b.formation.map(id=>`<span class="round-face"><span class="disc">${this.face(id)}</span><b>Lv.${b.heroes[id].level}</b></span>`).join('')}<i></i>${this.button(ico('people')+'<small>阵型</small>',()=>this.formation(),'quiet lineup-button')}</div>`;}
 private dungeons(){if(this.port.model().dungeon.run&&this.port.battle()!==this.port.model())return this.adventure();const b=this.port.model();let body='';
  if(this.dungeonTab===0)body=`<div class="dungeon-list">${[0,1,2,3].map(id=>`<article class="dungeon-card"><img src="${this.urls['dungeon'+id]}" alt="${DUNGEONS[id].name}"><div><h2>${DUNGEONS[id].name}</h2><div class="drop-icons">${this.dungeonRewards(id,0)}</div><footer><small>消耗体力 ${ico('bolt')}×10</small>${this.button('挑战',()=>this.challenge(id))}</footer></div></article>`).join('')}</div>`;
  else if(this.dungeonTab===1){const r=dungeonReward(5,0);body=`<article class="feature-card endless-card"><div class="feature-art" style="background-image:url('${this.urls.endlessArt||this.urls.dungeon3}')"><div class="feature-title"><div class="title-row">${LAUREL}<h2>无尽试炼</h2>${LAUREL.replace('class="laurel"','class="laurel mirror"')}</div><p class="ribbon">连续闯关，直到全队阵亡</p></div>${this.button(ico('question'),()=>this.info('无尽试炼','每关击败三名敌人，继续向更高层进发。全队阵亡后结算本次挑战奖励。'),'flat help-button',false,'无尽规则')}</div><div class="feature-panel"><div class="feature-row record">${ico('trophy')}<b>最高通关 <strong>${Math.max(0,b.dungeon.floor-1)}关</strong></b><i></i><small>本次从第1关开始</small></div><div class="feature-row"><b>每通关1关获得</b><div class="feature-rewards">${this.reward(6,r.gold,'金币')}<span>${this.reward(7,r.experience,'经验')}<small>每位英雄</small></span>${this.reward(7,r.materials,'强化石')}</div></div><div class="feature-row"><b>出战阵容</b>${this.lineup()}</div><div class="feature-row"><b>入场消耗 ${ico('bolt')}×10</b><i></i><small>单次入场，连续挑战</small>${this.button('挑战',()=>this.challenge(5),'go-button')}</div></div></article>`;}
  else{const left=2-b.dungeon.dailyUsed;body=`<article class="feature-card daily-card"><header><h2>${DUNGEONS[4].name}</h2><i></i><span class="today">${ico('calendar')}今日挑战 ${left}/2</span></header><div class="feature-art" style="background-image:url('${this.urls.dailyArt||this.urls.dungeon3}')"></div><div class="feature-panel"><div class="feature-row"><b>奖励预览</b><div class="feature-rewards">${this.reward(6,1500,'金币')}<span>${this.reward(7,600,'经验')}<small>每位英雄</small></span>${this.reward(7,15,'强化石')}</div></div><div class="feature-row"><b>出战阵容</b>${this.lineup()}</div><div class="feature-row"><b>消耗体力 ${ico('bolt')}×10</b>${this.button('挑战',()=>this.challenge(4),'go-button')}</div></div></article>`;}
  return `<div class="page dungeon-page" style="--scene:url('${this.urls.scene5}')">${this.wallet()}<div class="main-tabs">${['资源副本','无尽挑战','每日副本'].map((t,i)=>this.button(t,()=>{this.dungeonTab=i;this.draw();},this.dungeonTab===i?'selected':'quiet')).join('')}</div>${b.dungeon.run?this.button('继续挑战',()=>{this.port.resume();this.draw();},'resume-button'):''}${body}${this.nav('dungeon')}</div>`;}
 private challenge(id:number){const b=this.port.model(),cost=[10,15,20][this.difficulty];this.popup('副本挑战',`<div class="challenge-heading"><img src="${id===5?this.urls.endlessArt||this.urls.dungeon3:id===4?this.urls.dailyArt||this.urls.dungeon3:this.urls['dungeon'+id]}" alt=""><div><h3>${DUNGEONS[id].name}</h3><small>${id===5?'无限关卡 · 阵亡后结束':'共10波 · 末波首领'}</small>${id===4?'<small>今日剩余 '+(2-b.dungeon.dailyUsed)+'/2 次</small>':''}</div></div>${this.divider()}`+this.section('选择难度')+`<div class="main-tabs">${DIFFICULTIES.map((t,i)=>this.button(t,()=>{this.difficulty=i;this.challenge(id);},i===this.difficulty?'selected':'quiet')).join('')}</div>`+this.row('推荐等级','Lv.'+[1,8,15][this.difficulty])+this.divider()+this.section('奖励预览')+this.rewardViewport(this.dungeonRewards(id,this.difficulty))+this.row('当前体力',b.dungeon.stamina+'/120','bolt'),`<p class="challenge-cost">消耗体力 ${ico('bolt')}×${cost}</p>`+this.button('开始挑战',()=>{this.close();this.port.start(id,this.difficulty);this.draw();}),'large challenge-dialog');}
 private offline(){const b=this.port.model(),r=b.offline,cp=r?.checkpoint||b.highestWave,scale=1+Math.floor((cp-1)/5),sec=r?.seconds||0,clock=[Math.floor(sec/3600),Math.floor(sec%3600/60),Math.floor(sec%60)].map(n=>('0'+n).slice(-2)).join(':');this.popup('挂机奖励',`<p class="pool-name lined">镇外森林 · 检查点 ${cp}</p><div class="offline-rates">${this.resource(6,'+'+7200*scale+'/小时')}${this.resource(7,'+'+5760*scale+'/小时')}</div><p class="idle-time"><span>${ico('clock')}挂机时间 ${r?clock:'--:--:--'}</span><small>上限8小时</small></p>${this.divider()}`+this.rewardViewport(this.rewardList(b))+this.divider(),this.button('快速扫荡'+`<small>${ico('bolt')}×10</small>`,()=>this.quick(),'peach')+this.button('领取',()=>{const items=this.rewardList(b);this.run(m=>m.claimOffline(),()=>{this.draw();this.rewards(items);});},'',!r),'large');}
 private quick(){this.info('快速扫荡','消耗10体力，获得30分钟挂机收益？',()=>{let reward:OfflineReward|null=null;this.run(m=>{const result=m.quickSweep();reward=result.reward;return result.error;},()=>this.rewards(this.rewardItems(reward)));});}
 private rewards(items:string){this.popup('恭喜获得',this.rewardViewport(items),'','fullscreen rewards-fullscreen');}
 /** Formation slot placement: front row on the right, back row on the left (rates come from FORMATIONS). */
 private placement(rates:number[]){const even=Math.max(...rates)-Math.min(...rates)<5;if(even)return [{x:72,y:30,front:true},{x:48,y:52,front:false},{x:24,y:74,front:false}];if(rates[1]>=rates[0]*.9)return [{x:72,y:28,front:true},{x:72,y:72,front:true},{x:28,y:50,front:false}];return [{x:72,y:50,front:true},{x:28,y:22,front:false},{x:30,y:74,front:false}];}
 private formation(){const b=this.port.battle();let draft=b.formation.slice(),preset=this.port.model().interfaceProgress.preset;this.inSecondary=true;this.root.classList.remove('battle-mode');this.backdrop.style.display='none';
  const render=()=>{const f=FORMATIONS[this.port.model().interfaceProgress.formation],place=this.placement(f.rates);this.content.innerHTML=`<div class="secondary formation-page"><div class="formation-scene" style="background-image:url('${this.urls.scene1}')"><h1 class="title-plaque plaque">${this.plate('编队')}</h1><div class="standing-heroes">${[0,1,2].map(slot=>{const p=place[slot],style=`left:${p.x}%;top:${p.y}%`;return draft[slot]===undefined?this.button('＋',()=>this.toast('点击下方英雄卡片上阵'),'empty-position" style="'+style,false,'空位'):this.button(`<span class="role-tag">${this.roleBadge(draft[slot])}${NAMES[draft[slot]]} · ${ROLES[draft[slot]]}</span>${this.face(draft[slot])}<span class="row-plaque">${p.front?'前排':'后排'}</span><small>受击率 ${f.rates[slot]}%</small>`,()=>{draft.splice(slot,1);render();},'standing '+(p.front?'front':'back')+'" style="'+style,false,NAMES[draft[slot]]);}).join('')}</div></div><div class="formation-sheet"><div class="formation-toolbar"><b>已上阵 ${draft.length}/3</b><i></i><div class="preset-buttons">${[0,1,2,3].map(i=>this.button(String(i+1),()=>{preset=i;draft=this.port.model().interfaceProgress.presets[i].filter(id=>this.port.model().owns(id));render();},i===preset?'selected':'quiet')).join('')}</div><i></i><span class="formation-name">${f.name}</span>${this.button(ico('people')+'阵型选择',()=>this.formationTypes(render))}</div><div class="roster-grid">${HERO_CONFIG.map((h,id)=>this.button(this.heroCard(id,{deployed:draft.indexOf(id)>=0}),()=>{if(!this.port.model().owns(id)){this.toast('请先招募该英雄');return;}const i=draft.indexOf(id);if(i>=0)draft.splice(i,1);else if(draft.length<3)draft.push(id);else this.toast('最多上阵三名英雄，请先移除一位');render();},'flat',false,NAMES[id])).join('')}</div></div>${this.button('关闭',()=>{if(!draft.length){this.toast('至少上阵一名英雄');return;}const error=this.port.formation(draft);if(error){this.toast(error);return;}this.run(m=>{m.interfaceProgress.presets[preset]=draft.slice();m.interfaceProgress.preset=preset;return null;},()=>{this.port.navigate(this.page);this.draw();});},'secondary-close')}</div>`;};render();}
 private formationTypes(back:()=>void,pick=this.port.model().interfaceProgress.formation){const team=this.port.battle().formation,heroes=[0,1,2].map(n=>team[n]??[0,1,2].filter(i=>team.indexOf(i)<0)[n-team.length]??n);this.popup('阵型选择',`<div class="two-grid formation-types">${FORMATIONS.map((f,i)=>{const place=this.placement(f.rates);return this.button(`<header>${ico(['shield','sword','people','bolt'][i])}<h3>${f.name}</h3><small>后排 ➜ 前排</small><i class="radio ${pick===i?'on':''}">${pick===i?ico('check'):''}</i></header><div class="formation-mini">${[0,1,2].map(n=>`<div style="left:${place[n].x}%;top:${place[n].y}%">${this.face(heroes[n])}<b>受击率 ${f.rates[n]}%</b></div>`).join('')}</div>`,()=>this.formationTypes(back,i),'flat formation-option '+(pick===i?'picked':''),false,f.name);}).join('')}</div><p class="formation-note">${ico('leaf')}受击率决定敌人普通攻击的目标概率${ico('leaf','mirror')}</p>`,this.button('使用阵型',()=>this.run(m=>{m.interfaceProgress.formation=pick;return null;},()=>{this.port.battle().interfaceProgress.formation=pick;this.close();back();}),'wide'),'large');}
 update(){const now=performance.now();if(now-this.lastUpdate<50)return;this.lastUpdate=now;const b=this.port.battle();this.root.querySelectorAll('.wallet').forEach(wallet=>{const values=wallet.querySelectorAll('.resource b');if(values[0])values[0].textContent=String(this.port.model().gold);if(values[1]&&!wallet.querySelector('.ticket-resource'))values[1].textContent=this.port.model().dungeon.stamina+'/120';});if(this.root.classList.contains('battle-mode')){
  const checkpoint=this.root.querySelector('[data-live="checkpoint"]');if(checkpoint)checkpoint.textContent='下一检查点 · 第'+Math.ceil((b.wave+1)/10)*10+'波';const wave=this.root.querySelector('[data-live="wave"]');if(wave)wave.textContent=this.page==='dungeon'?'第'+b.wave+(this.port.model().dungeon.run?.id===5?'关':'波'):'第'+b.wave+'波';
  this.root.querySelectorAll<HTMLElement>('[data-turn]').forEach(n=>{const i=Number(n.dataset.turn);n.classList.toggle('turn-current',b.nextActor===i);if(i>=3){const image=n.querySelector('img');if(image&&image.src!==this.urls['monster'+b.enemies[i-3].kind])image.src=this.urls['monster'+b.enemies[i-3].kind];}});
  b.formation.forEach(id=>{const h=b.heroes[id],bar=this.root.querySelector<HTMLElement>(`[data-hp="${id}"]`),label=this.root.querySelector(`[data-hp-label="${id}"]`),shield=this.root.querySelector(`[data-shield="${id}"]`);if(bar)bar.style.width=Math.max(0,h.hp/b.stats(id).hp*100)+'%';if(label)label.textContent='♥ '+h.hp+'/'+b.stats(id).hp;if(shield)shield.textContent=h.shield>0?'⬟ '+h.shield:'';[0,1].forEach(j=>{const n=this.root.querySelector(`[data-cooldown="${id}-${j}"]`);if(n)n.textContent=(j?h.queued2:h.queued)?'待释放':(j?h.cooldown2:h.cooldown)>0?(j?h.cooldown2:h.cooldown).toFixed(1):'';});});
 }
 const receipt=this.port.model().dungeon.run?.receipt;if(receipt&&this.page==='dungeon'&&this.port.battle()!==this.port.model()){const key=JSON.stringify(receipt);if(this.lastReceipt!==key){this.lastReceipt=key;this.draw();this.result();}}else if(!receipt)this.lastReceipt='';
 const off=this.port.model().offline;if(off&&off!==this.lastOffline&&!this.modal.childElementCount&&!this.inSecondary){this.lastOffline=off;this.offline();}
 }
 private result(){const b=this.port.battle(),r=this.port.model().dungeon.run!,p=r.receipt!;this.popup(r.id===5?'无尽结算':b.result==='victory'?'挑战胜利':'挑战失败',`<p class="pool-name">${DUNGEONS[r.id].name} · ${DIFFICULTIES[r.difficulty]}</p><p class="result-line">通关 <em>${p.cleared}</em> ${r.id===5?'关':'波'} · 用时 ${Math.floor(b.elapsed)}秒</p>`+this.section('获得奖励')+this.rewardViewport(this.reward(6,p.gold,'金币',4)+this.reward(7,p.experience,'每位英雄经验')+this.reward(7,p.materials,'强化石')+(p.gear?this.reward(0,p.gear,'装备',3):''))+this.section('战斗统计')+b.formation.map(id=>this.row(NAMES[id],'伤害 '+b.heroes[id].damage+' / 治疗 '+b.heroes[id].healing,ROLE_ICONS[id])).join(''),this.button('退出',()=>{this.close();this.port.exit();this.draw();},'peach')+this.button('再次挑战',()=>{this.close();this.port.retry();this.lastReceipt='';this.draw();}),'large');}
 destroy(){this.root.remove();this.backdrop.remove();document.getElementById('second-edition-style')?.remove();document.removeEventListener('keydown',this.onKey);clearTimeout(this.toastTimer);}
}
